// SPDX-License-Identifier: LGPL-2.1-or-later
//! AudioCaps C ABI (`libaudiocaps.so`, header `include/audiocaps.h`, generated by cbindgen).
//!
//! Design:
//! - Opaque handles: [`AcContext`] (a probe context: system root, probe thread, generations),
//!   [`AcSnapshot`] (an immutable result; queries take no locks and do no I/O) and [`AcWatch`].
//! - Scope, options and results are JSON in the published schema
//!   (`schema/audiocaps-snapshot-v1.schema.json`); `NULL` scope means everything, `NULL` options
//!   the defaults (passive, per-backend deadlines, redaction on, no opt-ins).
//! - Strings returned as `char *` are owned by the caller: free them with [`ac_string_free`].
//!   Strings returned as `const char *` are borrowed from the handle they came from.
//! - Errors: functions return `NULL` (or a negative number) and set a thread-local message read
//!   with [`ac_last_error`].
//! - Events: [`ac_watch_new`] delivers a new snapshot and its diff for the watched scope, either on
//!   an internal thread ([`AC_WATCH_THREAD`]) or through a pollable fd and [`ac_watch_dispatch`] on
//!   the application's own thread (for Qt or GLib loops).
//!
//! This is the only crate that uses `unsafe`; it holds no logic beyond marshalling.

#![allow(unsafe_code)]

use std::cell::RefCell;
use std::collections::VecDeque;
use std::ffi::{CStr, CString, c_char, c_int, c_void};
use std::os::fd::{AsRawFd, OwnedFd};
use std::path::PathBuf;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;

use audiocaps_backends::{ProbeOptions, Runtime, SystemRoot};
use audiocaps_model::{
    AccessPath, ActiveProbeRequest, AppRequest, Direction, EndpointClass, EndpointId, FieldGroup,
    LayerKind, ProbeScope, RedactionPolicy, Selection, Snapshot,
};
use serde::Deserialize;

/// ABI version: bumped on any incompatible change to the functions in this header.
pub const AC_ABI_VERSION: u32 = 1;

/// Watch mode: the callback runs on an internal thread.
pub const AC_WATCH_THREAD: u32 = 1;
/// Watch mode: the callback runs from [`ac_watch_dispatch`] on the caller's thread; poll the fd
/// from [`ac_watch_fd`] for readability.
pub const AC_WATCH_DISPATCH: u32 = 0;

/// `ac_can_play` answers.
pub const AC_YES: c_int = 1;
/// The path can't carry the format.
pub const AC_NO: c_int = 0;
/// Not enough is known.
pub const AC_UNKNOWN: c_int = -1;
/// Bad arguments.
pub const AC_ERROR: c_int = -2;

thread_local! {
    static LAST_ERROR: RefCell<CString> = RefCell::new(CString::default());
}

fn set_error(msg: impl Into<String>) {
    let s = CString::new(msg.into().replace('\0', " ")).unwrap_or_default();
    LAST_ERROR.with(|e| *e.borrow_mut() = s);
}

/// A probe context.
pub struct AcContext {
    rt: Runtime,
}

/// An immutable snapshot.
pub struct AcSnapshot {
    snap: Arc<Snapshot>,
    ids: Vec<CString>,
}

impl AcSnapshot {
    fn new(snap: Arc<Snapshot>) -> Self {
        let ids = snap
            .endpoints
            .iter()
            .map(|e| CString::new(e.id.0.replace('\0', " ")).unwrap_or_default())
            .collect();
        Self { snap, ids }
    }
}

/// Watch callback: `snapshot` and `diff_json` are borrowed for the duration of the call; keep the
/// snapshot with [`ac_snapshot_clone`].
pub type AcWatchCallback = Option<
    unsafe extern "C" fn(user: *mut c_void, snapshot: *const AcSnapshot, diff_json: *const c_char),
>;

struct Pending {
    queue: Mutex<VecDeque<(Arc<Snapshot>, CString)>>,
}

/// A watch.
pub struct AcWatch {
    stop: Arc<AtomicBool>,
    forwarder: Option<thread::JoinHandle<()>>,
    pending: Arc<Pending>,
    read: Option<OwnedFd>,
    cb: AcWatchCallback,
    user: usize,
}

/// Options as JSON. Every field is optional.
#[derive(Debug, Default, Deserialize)]
#[serde(deny_unknown_fields)]
struct OptionsJson {
    /// Deadline per backend in milliseconds (0: wait for completion). Default 150.
    deadline_ms: Option<u64>,
    /// Opt-in: CEC queries.
    #[serde(default)]
    cec: bool,
    /// Opt-in: software codec check.
    #[serde(default)]
    software_codecs: bool,
    /// Opt-in: active probe.
    active_probe: Option<ActiveProbeRequest>,
    /// What the app will play.
    app: Option<AppRequest>,
    /// App quirk-pack directories.
    #[serde(default)]
    quirk_dirs: Vec<PathBuf>,
    /// App rule-pack directories.
    #[serde(default)]
    rule_dirs: Vec<PathBuf>,
    /// `false` turns redaction off (serials, Bluetooth addresses, personal names in the clear).
    redact: Option<bool>,
    /// A custom redaction policy.
    redaction: Option<RedactionPolicy>,
}

/// Reads a borrowed C string.
///
/// # Safety
/// `p` must be NULL or a valid NUL-terminated string.
unsafe fn cstr<'a>(p: *const c_char) -> Option<&'a str> {
    if p.is_null() {
        None
    } else {
        // SAFETY: the caller guarantees a valid NUL-terminated string.
        unsafe { CStr::from_ptr(p) }.to_str().ok()
    }
}

fn owned(s: String) -> *mut c_char {
    CString::new(s.replace('\0', " "))
        .map(CString::into_raw)
        .unwrap_or(std::ptr::null_mut())
}

/// One scope field: `"all"` or a list of items.
#[derive(Debug, Deserialize)]
#[serde(untagged)]
enum Sel<T> {
    Word(String),
    List(Vec<T>),
}

impl<T> Sel<T> {
    fn into_selection(self, field: &str) -> Result<Selection<T>, String> {
        match self {
            Sel::Word(w) if w == "all" => Ok(Selection::All),
            Sel::Word(w) => Err(format!(
                "scope.{field}: expected \"all\" or a list, got {w:?}"
            )),
            Sel::List(v) => Ok(Selection::Only(v)),
        }
    }
}

/// Scope as JSON: each field is `"all"` or a list; a missing field means all.
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct ScopeJson {
    endpoint_classes: Option<Sel<EndpointClass>>,
    directions: Option<Sel<Direction>>,
    endpoints: Option<Sel<EndpointId>>,
    layers: Option<Sel<LayerKind>>,
    fields: Option<Sel<FieldGroup>>,
    access_paths: Option<Sel<AccessPath>>,
}

fn sel<T>(v: Option<Sel<T>>, field: &str) -> Result<Selection<T>, String> {
    v.map_or(Ok(Selection::All), |s| s.into_selection(field))
}

fn parse_scope(s: Option<&str>) -> Result<ProbeScope, String> {
    let Some(t) = s else {
        return Ok(ProbeScope::everything());
    };
    let j: ScopeJson = serde_json::from_str(t).map_err(|e| format!("scope: {e}"))?;
    Ok(ProbeScope {
        endpoint_classes: sel(j.endpoint_classes, "endpoint_classes")?,
        directions: sel(j.directions, "directions")?,
        endpoints: sel(j.endpoints, "endpoints")?,
        layers: sel(j.layers, "layers")?,
        fields: sel(j.fields, "fields")?,
        access_paths: sel(j.access_paths, "access_paths")?,
    })
}

fn parse_options(s: Option<&str>) -> Result<ProbeOptions, String> {
    let j: OptionsJson = match s {
        None => OptionsJson::default(),
        Some(t) => serde_json::from_str(t).map_err(|e| format!("options: {e}"))?,
    };
    let mut o = match j.deadline_ms {
        Some(0) => ProbeOptions::unbounded(),
        Some(ms) => ProbeOptions {
            default_deadline: Some(Duration::from_millis(ms)),
            ..ProbeOptions::default()
        },
        None => ProbeOptions::default(),
    };
    if j.cec {
        o = o.with_cec();
    }
    if j.software_codecs {
        o = o.with_software_codecs();
    }
    if let Some(a) = j.active_probe {
        o = o.with_active_probe(a);
    }
    if let Some(a) = j.app {
        o = o.with_app(a);
    }
    o.quirk_dirs = j.quirk_dirs;
    o.rule_dirs = j.rule_dirs;
    o.redaction = match (j.redaction, j.redact) {
        (Some(p), _) => Some(p),
        (None, Some(false)) => Some(RedactionPolicy::keep_all()),
        _ => None,
    };
    Ok(o)
}

/// The ABI version of the loaded library ([`AC_ABI_VERSION`]).
#[unsafe(no_mangle)]
pub extern "C" fn ac_abi_version() -> u32 {
    AC_ABI_VERSION
}

/// The JSON schema version snapshots follow, e.g. `"1.6.0"` (static string).
#[unsafe(no_mangle)]
pub extern "C" fn ac_schema_version() -> *const c_char {
    static V: std::sync::OnceLock<CString> = std::sync::OnceLock::new();
    V.get_or_init(|| CString::new(audiocaps_model::SCHEMA_VERSION).unwrap_or_default())
        .as_ptr()
}

/// The last error on this thread (empty if none). Valid until the next failing call on the thread.
#[unsafe(no_mangle)]
pub extern "C" fn ac_last_error() -> *const c_char {
    LAST_ERROR.with(|e| e.borrow().as_ptr())
}

/// Frees a string returned by this library. NULL is ignored.
///
/// # Safety
/// `s` must be NULL or a string returned by this library, freed once.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ac_string_free(s: *mut c_char) {
    if !s.is_null() {
        // SAFETY: `s` came from CString::into_raw in this library.
        drop(unsafe { CString::from_raw(s) });
    }
}

/// A context for the running system. NULL on error.
#[unsafe(no_mangle)]
pub extern "C" fn ac_context_new() -> *mut AcContext {
    match Runtime::new(SystemRoot::Live) {
        Ok(rt) => Box::into_raw(Box::new(AcContext { rt })),
        Err(e) => {
            set_error(e.to_string());
            std::ptr::null_mut()
        }
    }
}

/// A context that replays an extracted capture (`audiocaps import`) instead of the live system.
/// NULL on error.
///
/// # Safety
/// `dir` must be a valid NUL-terminated path.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ac_context_new_fixture(dir: *const c_char) -> *mut AcContext {
    // SAFETY: forwarded caller guarantee.
    let Some(d) = (unsafe { cstr(dir) }) else {
        set_error("dir is NULL or not UTF-8");
        return std::ptr::null_mut();
    };
    match SystemRoot::fixture(d).and_then(Runtime::new) {
        Ok(rt) => Box::into_raw(Box::new(AcContext { rt })),
        Err(e) => {
            set_error(format!("{d}: {e}"));
            std::ptr::null_mut()
        }
    }
}

/// Frees a context. Snapshots taken from it stay valid. NULL is ignored.
///
/// # Safety
/// `ctx` must be NULL or a context from this library, freed once.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ac_context_free(ctx: *mut AcContext) {
    if !ctx.is_null() {
        // SAFETY: from Box::into_raw in this library.
        drop(unsafe { Box::from_raw(ctx) });
    }
}

/// Probes `scope_json` (NULL: everything) with `options_json` (NULL: defaults). Returns a snapshot
/// to free with [`ac_snapshot_free`], or NULL on error.
///
/// # Safety
/// `ctx` must be a valid context; the strings NULL or valid NUL-terminated UTF-8.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ac_probe(
    ctx: *mut AcContext,
    scope_json: *const c_char,
    options_json: *const c_char,
) -> *mut AcSnapshot {
    // SAFETY: caller passes a valid context or NULL.
    let Some(ctx) = (unsafe { ctx.as_ref() }) else {
        set_error("ctx is NULL");
        return std::ptr::null_mut();
    };
    // SAFETY: forwarded caller guarantee.
    let (scope, opts) = unsafe { (cstr(scope_json), cstr(options_json)) };
    let scope = match parse_scope(scope) {
        Ok(s) => s,
        Err(e) => {
            set_error(e);
            return std::ptr::null_mut();
        }
    };
    let opts = match parse_options(opts) {
        Ok(o) => o,
        Err(e) => {
            set_error(e);
            return std::ptr::null_mut();
        }
    };
    Box::into_raw(Box::new(AcSnapshot::new(ctx.rt.probe(&scope, &opts))))
}

/// A second handle to the same snapshot (cheap). Free both.
///
/// # Safety
/// `snap` must be a valid snapshot.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ac_snapshot_clone(snap: *const AcSnapshot) -> *mut AcSnapshot {
    // SAFETY: caller passes a valid snapshot or NULL.
    match unsafe { snap.as_ref() } {
        Some(s) => Box::into_raw(Box::new(AcSnapshot::new(s.snap.clone()))),
        None => {
            set_error("snapshot is NULL");
            std::ptr::null_mut()
        }
    }
}

/// Frees a snapshot. NULL is ignored.
///
/// # Safety
/// `snap` must be NULL or a snapshot from this library, freed once.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ac_snapshot_free(snap: *mut AcSnapshot) {
    if !snap.is_null() {
        // SAFETY: from Box::into_raw in this library.
        drop(unsafe { Box::from_raw(snap) });
    }
}

/// The snapshot's generation (increases with each probe of the context).
///
/// # Safety
/// `snap` must be a valid snapshot.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ac_snapshot_generation(snap: *const AcSnapshot) -> u64 {
    // SAFETY: caller passes a valid snapshot or NULL.
    unsafe { snap.as_ref() }.map_or(0, |s| s.snap.generation)
}

/// The whole snapshot as JSON (owned; free with [`ac_string_free`]).
///
/// # Safety
/// `snap` must be a valid snapshot.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ac_snapshot_json(snap: *const AcSnapshot) -> *mut c_char {
    // SAFETY: caller passes a valid snapshot or NULL.
    match unsafe { snap.as_ref() } {
        Some(s) => owned(serde_json::to_string(&*s.snap).unwrap_or_default()),
        None => {
            set_error("snapshot is NULL");
            std::ptr::null_mut()
        }
    }
}

/// Number of endpoints in the snapshot.
///
/// # Safety
/// `snap` must be a valid snapshot.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ac_snapshot_endpoint_count(snap: *const AcSnapshot) -> usize {
    // SAFETY: caller passes a valid snapshot or NULL.
    unsafe { snap.as_ref() }.map_or(0, |s| s.ids.len())
}

/// The id of endpoint `index` (borrowed from the snapshot), or NULL past the end.
///
/// # Safety
/// `snap` must be a valid snapshot.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ac_snapshot_endpoint_id(
    snap: *const AcSnapshot,
    index: usize,
) -> *const c_char {
    // SAFETY: caller passes a valid snapshot or NULL.
    unsafe { snap.as_ref() }
        .and_then(|s| s.ids.get(index))
        .map_or(std::ptr::null(), |c| c.as_ptr())
}

/// One endpoint as JSON (owned), or NULL if the id isn't in the snapshot.
///
/// # Safety
/// `snap` must be a valid snapshot; `id` a valid NUL-terminated string.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ac_snapshot_endpoint_json(
    snap: *const AcSnapshot,
    id: *const c_char,
) -> *mut c_char {
    // SAFETY: caller guarantees.
    let (Some(s), Some(id)) = (unsafe { snap.as_ref() }, unsafe { cstr(id) }) else {
        set_error("snapshot or id is NULL");
        return std::ptr::null_mut();
    };
    match s.snap.endpoints.iter().find(|e| e.id.0 == id) {
        Some(e) => owned(serde_json::to_string(e).unwrap_or_default()),
        None => {
            set_error(format!("no endpoint {id}"));
            std::ptr::null_mut()
        }
    }
}

/// The findings as a JSON array (owned).
///
/// # Safety
/// `snap` must be a valid snapshot.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ac_snapshot_findings_json(snap: *const AcSnapshot) -> *mut c_char {
    // SAFETY: caller passes a valid snapshot or NULL.
    match unsafe { snap.as_ref() } {
        Some(s) => owned(serde_json::to_string(&s.snap.findings).unwrap_or_default()),
        None => {
            set_error("snapshot is NULL");
            std::ptr::null_mut()
        }
    }
}

/// Can `endpoint_id` play `format_json` via `access_path` (`"alsa_direct"`, `"pulse_audio"`,
/// `"pipe_wire"`, `"jack"`)? `format_json` is `{"codec": "lpcm", "channels": 8, "rate_hz": 48000,
/// "bits": 24}` (all optional; codec defaults to LPCM). Returns [`AC_YES`], [`AC_NO`],
/// [`AC_UNKNOWN`] or [`AC_ERROR`]; when `reason` isn't NULL it receives an owned explanation
/// (NULL for yes). Needs `effective` in the probe scope.
///
/// # Safety
/// `snap` must be a valid snapshot; strings valid NUL-terminated UTF-8; `reason` NULL or writable.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ac_can_play(
    snap: *const AcSnapshot,
    endpoint_id: *const c_char,
    access_path: *const c_char,
    format_json: *const c_char,
    reason: *mut *mut c_char,
) -> c_int {
    let set_reason = |r: Option<String>| {
        if !reason.is_null() {
            // SAFETY: caller passes a writable pointer or NULL.
            unsafe { *reason = r.map_or(std::ptr::null_mut(), owned) };
        }
    };
    // SAFETY: caller guarantees.
    let (Some(s), Some(id), Some(path), Some(fmt)) = (
        unsafe { snap.as_ref() },
        unsafe { cstr(endpoint_id) },
        unsafe { cstr(access_path) },
        unsafe { cstr(format_json) },
    ) else {
        set_error("an argument is NULL or not UTF-8");
        set_reason(None);
        return AC_ERROR;
    };
    let path: AccessPath = match serde_json::from_value(serde_json::Value::String(path.into())) {
        Ok(p) => p,
        Err(_) => {
            set_error(format!("unknown access path {path}"));
            set_reason(None);
            return AC_ERROR;
        }
    };
    let format: AppRequest = match serde_json::from_str(fmt) {
        Ok(f) => f,
        Err(e) => {
            set_error(format!("format: {e}"));
            set_reason(None);
            return AC_ERROR;
        }
    };
    match audiocaps_rules::query::can_play(&s.snap, &EndpointId(id.into()), path, &format) {
        audiocaps_rules::query::Answer::Yes => {
            set_reason(None);
            AC_YES
        }
        audiocaps_rules::query::Answer::No(r) => {
            set_reason(Some(r));
            AC_NO
        }
        audiocaps_rules::query::Answer::Unknown(r) => {
            set_reason(Some(r));
            AC_UNKNOWN
        }
    }
}

/// Watches `scope_json` with `options_json` and delivers each new snapshot with its diff to `cb`.
/// The first delivery is the initial snapshot. `mode` is [`AC_WATCH_THREAD`] or
/// [`AC_WATCH_DISPATCH`]. Returns a watch to free with [`ac_watch_free`], or NULL on error.
///
/// # Safety
/// `ctx` must be a valid context; strings NULL or valid; `cb` valid for the watch's lifetime and,
/// in thread mode, callable from another thread with `user`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ac_watch_new(
    ctx: *mut AcContext,
    scope_json: *const c_char,
    options_json: *const c_char,
    mode: u32,
    cb: AcWatchCallback,
    user: *mut c_void,
) -> *mut AcWatch {
    // SAFETY: caller guarantees.
    let Some(ctx) = (unsafe { ctx.as_ref() }) else {
        set_error("ctx is NULL");
        return std::ptr::null_mut();
    };
    if cb.is_none() {
        set_error("callback is NULL");
        return std::ptr::null_mut();
    }
    // SAFETY: forwarded caller guarantee.
    let (scope, opts) = unsafe { (cstr(scope_json), cstr(options_json)) };
    let (scope, opts) = match (parse_scope(scope), parse_options(opts)) {
        (Ok(s), Ok(o)) => (s, o),
        (Err(e), _) | (_, Err(e)) => {
            set_error(e);
            return std::ptr::null_mut();
        }
    };
    let watch = match ctx.rt.watch(&scope, &opts) {
        Ok(w) => w,
        Err(e) => {
            set_error(e.to_string());
            return std::ptr::null_mut();
        }
    };
    let stop = Arc::new(AtomicBool::new(false));
    let pending = Arc::new(Pending {
        queue: Mutex::new(VecDeque::new()),
    });
    let (read, write) = if mode == AC_WATCH_DISPATCH {
        match nix::unistd::pipe2(nix::fcntl::OFlag::O_NONBLOCK | nix::fcntl::OFlag::O_CLOEXEC) {
            Ok((r, w)) => (Some(r), Some(w)),
            Err(e) => {
                set_error(format!("pipe: {e}"));
                return std::ptr::null_mut();
            }
        }
    } else {
        (None, None)
    };
    let user_addr = user as usize;
    let st = stop.clone();
    let pq = pending.clone();
    let forwarder = thread::Builder::new()
        .name("audiocaps-events".into())
        .spawn(move || {
            while !st.load(Ordering::SeqCst) {
                let Some(ev) = watch.recv_timeout(Duration::from_millis(100)) else {
                    continue;
                };
                let diff = CString::new(serde_json::to_string(&ev.diff).unwrap_or_default())
                    .unwrap_or_default();
                match &write {
                    Some(w) => {
                        pq.queue
                            .lock()
                            .unwrap_or_else(|e| e.into_inner())
                            .push_back((ev.snapshot, diff));
                        let _ = nix::unistd::write(w, &[1u8]);
                    }
                    None => {
                        let s = AcSnapshot::new(ev.snapshot);
                        if let Some(f) = cb {
                            // SAFETY: the caller made `cb` and `user` valid for this thread.
                            unsafe { f(user_addr as *mut c_void, &s, diff.as_ptr()) };
                        }
                    }
                }
            }
            drop(watch);
        });
    let forwarder = match forwarder {
        Ok(h) => h,
        Err(e) => {
            set_error(e.to_string());
            return std::ptr::null_mut();
        }
    };
    Box::into_raw(Box::new(AcWatch {
        stop,
        forwarder: Some(forwarder),
        pending,
        read,
        cb,
        user: user_addr,
    }))
}

/// The fd to poll for readability in dispatch mode (-1 in thread mode).
///
/// # Safety
/// `w` must be a valid watch.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ac_watch_fd(w: *const AcWatch) -> c_int {
    // SAFETY: caller passes a valid watch or NULL.
    unsafe { w.as_ref() }
        .and_then(|w| w.read.as_ref())
        .map_or(-1, |fd| fd.as_raw_fd())
}

/// In dispatch mode, delivers every pending update to the callback on this thread. Returns how
/// many were delivered (0 in thread mode).
///
/// # Safety
/// `w` must be a valid watch; call from one thread at a time.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ac_watch_dispatch(w: *mut AcWatch) -> c_int {
    // SAFETY: caller passes a valid watch or NULL.
    let Some(w) = (unsafe { w.as_ref() }) else {
        return 0;
    };
    let Some(read) = &w.read else { return 0 };
    let mut buf = [0u8; 64];
    while matches!(nix::unistd::read(read, &mut buf), Ok(n) if n > 0) {}
    let items: Vec<_> = w
        .pending
        .queue
        .lock()
        .unwrap_or_else(|e| e.into_inner())
        .drain(..)
        .collect();
    let n = items.len();
    for (snap, diff) in items {
        let s = AcSnapshot::new(snap);
        if let Some(f) = w.cb {
            // SAFETY: the caller made `cb` and `user` valid.
            unsafe { f(w.user as *mut c_void, &s, diff.as_ptr()) };
        }
    }
    c_int::try_from(n).unwrap_or(c_int::MAX)
}

/// Stops and frees a watch. In thread mode, waits for a running callback to return. NULL is
/// ignored.
///
/// # Safety
/// `w` must be NULL or a watch from this library, freed once, not from inside its callback.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn ac_watch_free(w: *mut AcWatch) {
    if w.is_null() {
        return;
    }
    // SAFETY: from Box::into_raw in this library.
    let mut w = unsafe { Box::from_raw(w) };
    w.stop.store(true, Ordering::SeqCst);
    if let Some(h) = w.forwarder.take() {
        let _ = h.join();
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn options_parse() {
        assert!(parse_options(None).unwrap().default_deadline.is_some());
        let o = parse_options(Some(r#"{"deadline_ms":0,"cec":true,"redact":false}"#)).unwrap();
        assert!(o.cec && o.default_deadline.is_none());
        assert_eq!(o.redaction, Some(RedactionPolicy::keep_all()));
        assert!(parse_options(Some(r#"{"nope":1}"#)).is_err());
        assert_eq!(parse_scope(Some("{}")).unwrap(), ProbeScope::everything());
        let s = parse_scope(Some(
            r#"{"endpoint_classes":["hardware"],"fields":["effective"]}"#,
        ))
        .unwrap();
        assert!(
            s.fields.includes(&FieldGroup::Effective) && !s.fields.includes(&FieldGroup::Findings)
        );
        assert!(parse_scope(Some(r#"{"layers":"some"}"#)).is_err());
    }
}
